import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

import API from '../services/api';

import Sidebar from '../components/Sidebar';
import SummaryCards from '../components/SummaryCards';
import Alerts from '../components/Alerts';
import CostCard from '../components/CostCard';
import Graph from '../components/Graph';

function Dashboard() {

    const [insights, setInsights] = useState(null);
    const [alerts, setAlerts] = useState([]);
    const [cost, setCost] = useState(null);
    const [energyData, setEnergyData] = useState([]);
    const [devices, setDevices] = useState([]);

    useEffect(() => {

        const fetchInsights = async () => {
            try {
                const response = await API.get('/insights');
                setInsights(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchAlerts = async () => {
            try {
                const response = await API.get('/alerts');
                setAlerts(response.data.alerts);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchCost = async () => {
            try {
                const response = await API.get('/cost');
                setCost(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchData = async () => {
            try {
                const response = await API.get('/data');
                setEnergyData(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        const fetchDevices = async () => {
            try {
                const response = await API.get('/device');
                setDevices(response.data);
            } catch (error) {
                console.log(error);
            }
        };

        fetchInsights();
        fetchAlerts();
        fetchCost();
        fetchData();
        fetchDevices();

        const interval = setInterval(() => {
            fetchInsights();
            fetchAlerts();
            fetchCost();
            fetchData();
            fetchDevices();
        }, 5000);

        return () => clearInterval(interval);

    }, []);

    const turnOffDevice = async (deviceId) => {
        try {
            await API.post(`/device/${deviceId}/turn-off`);
            setDevices(devices.map(d => d._id === deviceId ? { ...d, status: 'OFF' } : d));
        } catch (error) {
            console.log(error);
        }
    };

    if (!insights) {
        return (
            <div className="flex min-h-screen bg-surface">
                <Sidebar />
                <div className="pl-72 flex-1 flex items-center justify-center">
                    <div className="flex flex-col items-center gap-4">
                        <div className="w-12 h-12 rounded-full border-2 border-vibrant-violet border-t-transparent animate-spin" />
                        <p className="text-on-surface-variant text-body-md font-inter">Loading Dashboard...</p>
                    </div>
                </div>
            </div>
        );
    }

    // Group energy readings by device so each device gets its own graph.
    const readingsByDevice = {};
    energyData.forEach((item) => {
        const key = item.device ? item.device._id : 'unknown';
        if (!readingsByDevice[key]) readingsByDevice[key] = [];
        readingsByDevice[key].push(item);
    });

    // Calculate total live power for header badge
    const totalLivePower = devices.reduce((sum, d) => {
        const readings = readingsByDevice[d._id] || [];
        if (readings.length > 0) return sum + readings[readings.length - 1].power;
        return sum;
    }, 0);

    return (

        <div className="flex min-h-screen bg-surface text-on-surface font-inter">

            {/* SIDEBAR */}
            <Sidebar />

            {/* MAIN CONTENT AREA */}
            <div className="pl-72 flex-1">

                {/* TOP HEADER BAR */}
                <header className="fixed top-0 left-72 right-0 h-16 bg-surface-dim/70 backdrop-blur-2xl z-40 flex items-center justify-between px-6 border-b border-glass-stroke">
                    <div />
                    <div className="flex items-center gap-6">
                        {/* Live power badge */}
                        <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-surface-container text-on-surface-variant">
                            <span className="material-symbols-outlined text-[18px] text-vibrant-violet">bolt</span>
                            <span className="text-data-mono font-mono">
                                {(totalLivePower / 1000).toFixed(1)} kW
                            </span>
                        </div>

                        {/* Notifications */}
                        <button className="p-2 text-on-surface-variant hover:text-electric-blue transition-colors relative">
                            <span className="material-symbols-outlined">notifications</span>
                            {alerts.length > 1 && (
                                <div className="absolute top-1 right-1 w-2 h-2 rounded-full bg-error-red" />
                            )}
                        </button>

                        {/* User */}
                        <div className="flex items-center gap-3 pl-4 border-l border-glass-stroke">
                            <div className="text-right hidden sm:block">
                                <div className="text-label-caps text-on-surface uppercase">Dashboard</div>
                                <div className="text-[10px] text-on-surface-variant/70 uppercase tracking-widest">Admin</div>
                            </div>
                            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center">
                                <span className="material-symbols-outlined text-white text-[18px]">person</span>
                            </div>
                        </div>
                    </div>
                </header>

                {/* PAGE CONTENT */}
                <main className="pt-16 min-h-screen">
                    <div className="flex flex-col w-full p-6 gap-8">

                        {/* SUMMARY CARDS */}
                        <SummaryCards insights={insights} />

                        {/* MAIN GRID: Graphs + Cost */}
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                            <div className="lg:col-span-2 space-y-6">
                                {devices.length === 0 && (
                                    <div className="glass-card p-8 text-center">
                                        <div className="w-16 h-16 rounded-full border border-glass-stroke flex items-center justify-center text-on-surface-variant mx-auto mb-4">
                                            <span className="material-symbols-outlined text-[32px]">devices</span>
                                        </div>
                                        <p className="text-on-surface-variant text-body-md">
                                            No devices yet.{' '}
                                            <Link to="/devices" className="text-electric-blue hover:underline">
                                                Add your first device
                                            </Link>{' '}
                                            to start seeing live graphs here.
                                        </p>
                                    </div>
                                )}

                                {devices.map((device) => {
                                    const deviceReadings = readingsByDevice[device._id] || [];
                                    const latestPower = deviceReadings.length > 0
                                        ? deviceReadings[deviceReadings.length - 1].power
                                        : null;
                                    const overLimit = latestPower !== null && latestPower > device.powerLimit;

                                    return (
                                        <div key={device._id}>
                                            <div className="flex justify-between items-center mb-3 px-1">
                                                <div className="flex items-center gap-3">
                                                    <span className="text-title-md font-inter font-medium text-on-surface">
                                                        {device.name}
                                                    </span>
                                                    <span className={`
                                                        px-3 py-1 rounded-full text-label-caps uppercase tracking-widest flex items-center gap-1.5
                                                        ${device.status === 'ON'
                                                            ? 'bg-electric-blue/10 text-electric-blue border border-electric-blue/20'
                                                            : 'bg-surface-container text-on-surface-variant border border-glass-stroke'}
                                                    `}>
                                                        <span className={`w-1.5 h-1.5 rounded-full ${device.status === 'ON' ? 'bg-electric-blue animate-pulse' : 'bg-on-surface-variant/50'}`} />
                                                        {device.status}
                                                    </span>
                                                    {overLimit && (
                                                        <span className="px-3 py-1 rounded-full text-label-caps uppercase bg-error/10 text-error-red border border-error/20 flex items-center gap-1">
                                                            <span className="material-symbols-outlined text-[12px]">warning</span>
                                                            Over limit ({device.powerLimit}W)
                                                        </span>
                                                    )}
                                                </div>
                                                {device.status === 'ON' && (
                                                    <button
                                                        onClick={() => turnOffDevice(device._id)}
                                                        className="text-label-caps uppercase bg-error/10 text-error-red px-4 py-2 rounded-lg hover:bg-error/20 border border-error/20 transition-colors flex items-center gap-1.5"
                                                    >
                                                        <span className="material-symbols-outlined text-[14px]">power_settings_new</span>
                                                        Turn OFF
                                                    </button>
                                                )}
                                            </div>

                                            {deviceReadings.length > 0 ? (
                                                <Graph data={deviceReadings} title={`${device.name} - Power Usage`} />
                                            ) : (
                                                <div className="glass-card p-6 text-on-surface-variant text-body-md flex items-center gap-3">
                                                    <span className="material-symbols-outlined text-on-surface-variant/50">sensors_off</span>
                                                    No readings from "{device.name}" yet. Waiting for sensor data...
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>

                            <div>
                                {cost &&
                                    <CostCard cost={cost} />
                                }
                            </div>

                        </div>

                        {/* ALERTS */}
                        <div>
                            <Alerts alerts={alerts} />
                        </div>

                    </div>
                </main>

            </div>

        </div>

    );

}

export default Dashboard;
